'use strict'

import { Uri } from 'vscode'
import { read } from './tagIndex'

// data/django-docs.json, generated by syntaxes/update_builtins.py from the objects.inv of the Django docs:
// the page of each tag and filter, like "ref/templates/builtins/"
interface Docs {
    version: string
    tags: Record<string, string>
    filters: Record<string, string>
}

// The docs of these tags are better explained in a guide than in the list of the built-in tags
const GUIDES: Record<string, string> = {
    block: 'ref/templates/language/#template-inheritance',
}

export class DjangoDocs {

    private docs: Promise<Docs>

    constructor(extensionUri: Uri) {
        this.docs = read(Uri.joinPath(extensionUri, 'data/django-docs.json')).then(text => JSON.parse(text))
    }

    // https://docs.djangoproject.com/en/6.0/ref/templates/builtins/#std-templatetag-firstof
    // for the version of Django of the project, or the stable version when it's not known.
    public async url(kind: 'tag' | 'filter', name: string, version = 'stable'): Promise<Uri | undefined> {
        if (kind === 'tag' && Object.prototype.hasOwnProperty.call(GUIDES, name)) {
            return Uri.parse(`https://docs.djangoproject.com/en/${version}/${GUIDES[name]}`)
        }
        const docs = await this.docs
        const pages = kind === 'tag' ? docs.tags : docs.filters
        if (!Object.prototype.hasOwnProperty.call(pages, name)) return undefined
        return Uri.parse(`https://docs.djangoproject.com/en/${version}/${pages[name]}#std-template${kind}-${name}`)
    }
}
